  /* ---------- tiny 3D scene: oblique view (t=0) → top view (t=1) ---------- */
  function scene(s, svg, objs, cfg) {
    const g = s.el("g"); svg.append(g);
    const parts = objs.slice().sort((a, c) => (c.h < 0.05) - (a.h < 0.05) || (a.y + a.d) - (c.y + c.d) || c.x - a.x).map(o => {
      const left = s.el("polygon", { fill: shade(o.c, 0.7), stroke: shade(o.c, 0.5), "stroke-width": 1 });
      const front = s.el("polygon", { fill: shade(o.c, 0.82), stroke: shade(o.c, 0.5), "stroke-width": 1 });
      const top = o.round ? s.el("ellipse", { fill: o.c, stroke: shade(o.c, 0.6), "stroke-width": 1.5 }) : s.el("polygon", { fill: o.c, stroke: shade(o.c, 0.55), "stroke-width": 1.5 });
      g.append(left, front, top); return { o, left, front, top };
    });
    const pr = (x, y, z, t) => {
      const ox = cfg.ox + t * (cfg.dx || 0);
      return [ox + (x + y * cfg.sh * (1 - t)) * cfg.k, cfg.oy + y * cfg.k * (cfg.sq + (1 - cfg.sq) * t) - z * cfg.k * 0.9 * (1 - t)];
    };
    const pts = a => a.map(p => p.join(",")).join(" ");
    const set = t => {
      for (const { o, left, front, top } of parts) {
        const z0 = o.z || 0, z1 = z0 + o.h;
        left.setAttribute("points", pts([pr(o.x, o.y, z0, t), pr(o.x, o.y + o.d, z0, t), pr(o.x, o.y + o.d, z1, t), pr(o.x, o.y, z1, t)]));
        front.setAttribute("points", pts([pr(o.x, o.y + o.d, z0, t), pr(o.x + o.w, o.y + o.d, z0, t), pr(o.x + o.w, o.y + o.d, z1, t), pr(o.x, o.y + o.d, z1, t)]));
        if (o.round) {
          const [cx, cy] = pr(o.x + o.w / 2, o.y + o.d / 2, z1, t);
          top.setAttribute("cx", cx); top.setAttribute("cy", cy); top.setAttribute("rx", o.w / 2 * cfg.k); top.setAttribute("ry", o.d / 2 * cfg.k * (cfg.sq + (1 - cfg.sq) * t));
        } else top.setAttribute("points", pts([pr(o.x, o.y, z1, t), pr(o.x + o.w, o.y, z1, t), pr(o.x + o.w, o.y + o.d, z1, t), pr(o.x, o.y + o.d, z1, t)]));
      }
    };
    set(0);
    return { set, pr };
  }

