  /* ---------- world helpers (lon/lat rings: [continent, lon, lat, lon, lat …]) ---------- */
  const CONT = ["Afrika", "Asien", "Europa", "Nordamerika", "Südamerika", "Australien", "Antarktis"];
  const CCOL = ["#e8b04b", "#e58b6a", "#8fbf6a", "#c98fd6", "#e0cf5f", "#e07a9c", "#e9eef3"];
  const D2R = Math.PI / 180;
  function ortho(lon, lat, lon0, lat0, R) {
    const l = lon * D2R, p = lat * D2R, l0 = lon0 * D2R, p0 = lat0 * D2R;
    const cosc = Math.sin(p0) * Math.sin(p) + Math.cos(p0) * Math.cos(p) * Math.cos(l - l0);
    let x = R * Math.cos(p) * Math.sin(l - l0), y = R * (Math.cos(p0) * Math.sin(p) - Math.sin(p0) * Math.cos(p) * Math.cos(l - l0));
    if (cosc < 0) { const h = Math.hypot(x, y) || 1; x = x / h * R; y = y / h * R; }
    return [x, -y, cosc >= 0];
  }
  function drawGlobe(g, cx, cy, R, lon0, lat0, opts = {}) {
    g.save();
    g.fillStyle = "#bfe0f5"; g.beginPath(); g.arc(cx, cy, R, 0, 7); g.fill();
    for (const ring of LL) {
      let any = false; const pts = [];
      for (let i = 1; i < ring.length; i += 2) { const q = ortho(ring[i], ring[i + 1], lon0, lat0, R); pts.push(q); if (q[2]) any = true; }
      if (!any) continue;
      g.fillStyle = g.strokeStyle = opts.mono ? "#9ccf86" : CCOL[ring[0]]; g.lineWidth = 1.2; g.lineJoin = "round";
      g.beginPath(); pts.forEach(([x, y], i) => i ? g.lineTo(cx + x, cy + y) : g.moveTo(cx + x, cy + y)); g.closePath(); g.fill(); g.stroke();
    }
    const line = (fn, col, w) => {
      g.strokeStyle = col; g.lineWidth = w; g.beginPath(); let pen = false;
      for (let k = 0; k <= 120; k++) { const [lon, lat] = fn(k / 120); const q = ortho(lon, lat, lon0, lat0, R); if (q[2]) { pen ? g.lineTo(cx + q[0], cy + q[1]) : g.moveTo(cx + q[0], cy + q[1]); pen = true; } else pen = false; }
      g.stroke();
    };
    if (opts.lat) for (const la of opts.lat) line(u => [-180 + 360 * u, la], "rgba(27,39,64,.45)", 1.5);
    if (opts.lon) for (const lo of opts.lon) line(u => [lo, -90 + 180 * u], "rgba(27,39,64,.45)", 1.5);
    if (opts.eq) line(u => [-180 + 360 * u, 0], P.red, 4 * opts.eq);
    if (opts.pm) line(u => [0, -90 + 180 * u], P.blue, 4 * opts.pm);
    g.strokeStyle = P.ink; g.lineWidth = 3; g.beginPath(); g.arc(cx, cy, R, 0, 7); g.stroke();
    g.restore();
  }

