          s.step(async () => { s.sfx.whoosh(); cap.textContent = "Jetzt ziehen wir die Streifen in die Breite, bis keine Lücken mehr da sind."; s.show(cap, "fade"); await s.tween({ from: 1, to: 0, dur: 2000, update: v => m = v }); s.sfx.snap(); });
