          const elev = x => { for (let i = 1; i < prof.length; i++) { const [x0, m0] = prof[i - 1], [x1, m1] = prof[i]; if (x <= x1) return m0 + (m1 - m0) * (x - x0) / (x1 - x0); } return prof[prof.length - 1][1]; };
