          svg.append(s.el("defs", null, s.el("clipPath", { id: clipId }, s.el("path", { d }))));
          const ground = s.el("g", { "clip-path": `url(#${clipId})` });
          zones.forEach(([a, c, , col]) => ground.append(s.el("rect", { x: a, y: 0, width: c - a, height: H, fill: col })));
