          const card = (col, head, txt) => s.h("div", { class: "card later", style: { padding: "10px 14px", borderTop: `8px solid ${col}` } }, s.h("p", { class: "t", style: { fontWeight: 700, color: P.ink } }, head), s.h("p", { class: "small" }, txt));
