          const c2 = s.h("div", { class: "card later" }, s.h("p", { class: "h2", style: { color: "var(--unit)", fontSize: "25px" } }, "Navi-App auf dem Handy"), s.h("p", { class: "small" }, "Ein blauer Punkt zeigt, wo du bist. Die Karte dreht sich mit und berechnet deinen Weg."));
          const c3 = s.h("div", { class: "card later" }, s.h("p", { class: "h2", style: { color: "var(--unit)", fontSize: "25px" } }, "Wanderkarte"), s.h("p", { class: "small" }, "Sehr genau, oft 1 : 25.000. Mit Wegen, Hütten und Aussichtspunkten in der Legende."));
